using System.Net.Http.Json;
using ReconciliationPlatform.Core;
namespace ReconciliationPlatform.Notifications; public sealed class HttpNotificationGateway(HttpClient client) : INotificationGateway { public async Task SendAsync(Guid id, string correlation, CancellationToken ct) { using var response = await client.PostAsJsonAsync("notifications", new { CaseId = id, CorrelationId = correlation }, ct); response.EnsureSuccessStatusCode(); } } public sealed class NotificationWorker(IServiceScopeFactory scopes) : BackgroundService { protected override async Task ExecuteAsync(CancellationToken ct) { while (!ct.IsCancellationRequested) { await using var scope = scopes.CreateAsyncScope(); if (!await scope.ServiceProvider.GetRequiredService<NotificationService>().ProcessNextAsync(ct)) await Task.Delay(500, ct); } } }
